import { useState } from "react";

export function CounterPair() {
  const [left, setLeft] = useState(0);
  const [right, setRight] = useState(0);
  return (
    <>
      <button type="button" onClick={() => setLeft((n) => n + 1)}>L: {left}</button>
      <button type="button" onClick={() => setRight((n) => n + 1)}>R: {right}</button>
      <p>Сумма: {left + right}</p>
    </>
  );
}
